#include "thinkercad/sensorbus.hpp"
#include <iostream>
#include <stdexcept>
using namespace thinkercad;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(){
    CircuitDocument document;Esp8266Board board;board.pinMode(4,PinMode::Input);SensorBus bus;
    auto add=[&](const std::string& model){const auto id=document.addPart(PartKind::Module,200,0);document.part(id).model=model;document.connect({id,"VCC"},{"board","3V3"});document.connect({id,"GND"},{"board","GND"});document.connect({id,model=="ds18b20"?"DQ":"DATA"},{"board","GPIO4"});return id;};
    Microseconds now=0;auto command=[&](int op,int byte=0){return bus.oneWire(document,document.solve(board),"board",4,op,byte,now,true);};
    require(command(0)==0,"empty 1-Wire bus has no presence");const auto id=add("ds18b20");document.part(id).parameters["temperature"]=-12.5;require(command(0)==1,"powered thermometer presence");std::vector<std::uint8_t> rom;for(int i=0;i<8;++i)rom.push_back(command(5,i));require(rom[0]==0x28&&ModuleDevices::crc8({rom.begin(),rom.begin()+7})==rom[7],"stable ROM family and CRC");require(command(5,8)==-1,"search terminates after actual devices");
    command(1,0xcc);command(1,0x44);require(command(3)==0,"conversion remains busy on virtual time");now=749999;require(command(3)==0,"12-bit conversion requires 750 ms");now=750000;require(command(3)==1,"conversion complete");command(0);command(1,0x55);for(auto value:rom)command(1,value);command(1,0xbe);std::vector<std::uint8_t> scratch;for(int i=0;i<9;++i)scratch.push_back(command(2));require(std::int16_t((scratch[1]<<8)|scratch[0])==-200,"negative DS18B20 temperature encoding");require(ModuleDevices::crc8({scratch.begin(),scratch.begin()+8})==scratch[8],"scratchpad CRC");
    command(0);command(1,0xcc);command(1,0x4e);command(1,80);command(1,0);command(1,0x1f);command(1,0x44);now+=93749;require(command(3)==0,"9-bit conversion still busy before 93.75 ms");++now;require(command(3)==1,"resolution changes conversion time");
    command(1,0x48);auto unpowered=document.solve(board);unpowered.voltage[{id,"VCC"}]=0;bus.synchronizePower(document,unpowered);command(0);command(1,0xcc);command(1,0xbe);std::vector<std::uint8_t> reset;for(int i=0;i<9;++i)reset.push_back(command(2));require(reset[0]==0x50&&reset[1]==5,"power cycle restores power-on temperature until conversion");require(reset[2]==80&&reset[4]==0x1f,"copied EEPROM configuration survives power cycle");
    command(0);command(1,0xec);std::vector<std::uint8_t> found(8,0);for(int bit=0;bit<64;++bit){const int value=command(3),complement=command(3);require(value!=complement,"single alarm device supplies ROM and complement bits");found[bit/8]|=value<<(bit%8);command(7,value);}require(found==rom,"bitwise alarm search used by genuine DallasTemperature returns ROM");
    const auto second=add("ds18b20");require(command(5,8)>=0&&command(5,16)==-1,"multidrop search lists both physical devices");document.removePart(second);board.pinMode(4,PinMode::Output);board.digitalWrite(4,false);require(command(0)==0,"shorted data line blocks presence");board.pinMode(4,PinMode::Input);document.removePart(id);
    const auto dht=add("dht22");document.part(dht).parameters={{"temperature",-10.5},{"humidity",62.3}};auto readDht=[&]{std::vector<std::uint8_t> bytes;for(int i=0;i<5;++i)bytes.push_back(bus.dht(document,document.solve(board),"board",4,i,now));return bytes;};auto data=readDht();require(data==std::vector<std::uint8_t>({2,111,128,105,90}),"DHT signed temperature, humidity and checksum");document.part(dht).parameters["temperature"]=30;require(readDht()==data,"DHT retains measurement during minimum sample interval");now+=2000000;require(readDht()[2]==1&&readDht()[3]==44,"DHT samples updated environment after two seconds");add("dht22");require(bus.dht(document,document.solve(board),"board",4,0,now)==-1,"DHT line collision rejects reading");
    std::cout<<"1-Wire ROM, CRC, conversion timing, multidrop and DHT sampling checks passed\n";
}
